/**
 * Tests for WebSocket project binding behavior
 * Spec: @multi-directory-daemon (ac-21, ac-21b, ac-22, ac-23)
 */

import { describe, it, expect } from 'vitest';
import { readFile } from 'fs/promises';
import { join } from 'path';

describe('WebSocket Project Binding', () => {
  describe('Connection Binding Implementation', () => {
    let serverContent: string;

    // AC: @multi-directory-daemon ac-21
    it('should read X-Kspec-Dir header during WebSocket upgrade handshake', async () => {
      // Read the server implementation (where WebSocket upgrade happens)
      serverContent = await readFile(
        join(process.cwd(), 'packages/daemon/src/server.ts'),
        'utf-8'
      );

      // Verify upgrade handler reads X-Kspec-Dir header
      // The server should read the header during WebSocket upgrade
      expect(serverContent).toMatch(/x-kspec-dir/i);
    });

    // AC: @multi-directory-daemon ac-21
    it('should bind connection to project path for its lifetime', async () => {
      serverContent = await readFile(
        join(process.cwd(), 'packages/daemon/src/server.ts'),
        'utf-8'
      );

      // Verify projectPath is stored during upgrade
      expect(serverContent).toContain('projectPath');

      // Check that ConnectionData type includes projectPath
      const typesContent = await readFile(
        join(process.cwd(), 'packages/daemon/src/websocket/types.ts'),
        'utf-8'
      );
      expect(typesContent).toContain('projectPath');
    });

    // AC: @multi-directory-daemon ac-21b
    it('should make project binding immutable (no mid-connection changes)', async () => {
      // The projectPath should be set once during upgrade and not modified
      // This is verified by checking that it's in ConnectionData (immutable after creation)
      const typesContent = await readFile(
        join(process.cwd(), 'packages/daemon/src/websocket/types.ts'),
        'utf-8'
      );

      // Verify ConnectionData has projectPath
      expect(typesContent).toContain('interface ConnectionData');
      expect(typesContent).toContain('projectPath');
    });

    // AC: @multi-directory-daemon ac-22
    it('should bind to default project when no X-Kspec-Dir header provided', async () => {
      serverContent = await readFile(
        join(process.cwd(), 'packages/daemon/src/server.ts'),
        'utf-8'
      );

      // Verify fallback to default project when header missing
      expect(serverContent).toMatch(/defaultProject|default.*project/i);
    });

    // AC: @multi-directory-daemon ac-23
    it('should reject connection with close code 4000 when no project specified and no default', async () => {
      serverContent = await readFile(
        join(process.cwd(), 'packages/daemon/src/server.ts'),
        'utf-8'
      );

      // Verify rejection logic exists with close code 4000
      expect(serverContent).toMatch(/4000/);
    });

    it('should include projectPath in ConnectionData type', async () => {
      const typesContent = await readFile(
        join(process.cwd(), 'packages/daemon/src/websocket/types.ts'),
        'utf-8'
      );

      // Verify ConnectionData has projectPath field
      expect(typesContent).toContain('interface ConnectionData');
      expect(typesContent).toMatch(/projectPath.*:/);
    });
  });

  describe('Project Binding Flow', () => {
