    82→            await projectManager.startWatcher(body.path);
    83→          } catch (error: any) {
    84→            // AC: @multi-directory-daemon ac-19 - Handle OS limits
    85→            if (error.message.includes('resource limit')) {
    86→              return errorResponse(503, {
    87→                error: 'Unable to watch project - resource limit reached',
    88→              });
    89→            }
    90→            throw error;
    91→          }
    92→
    93→          return {
    94→            success: true,
    95→            project: {
    96→              path: context.path,
    97→              registeredAt: context.registeredAt.toISOString(),
    98→              watcherStatus: context.watcherActive ? 'active' : 'stopped',
    99→            },
   100→          };
   101→        } catch (error: any) {
   102→          // AC: @multi-directory-daemon ac-5 - Invalid project (no .kspec/)
