   106→            });
   107→          }
   108→
   109→          // AC: @multi-directory-daemon ac-8b - Permission denied
   110→          if (error.code === 'EACCES' || error.code === 'EPERM') {
   111→            return errorResponse(403, {
   112→              error: `Permission denied - cannot read ${body.path}`,
   113→            });
   114→          }
   115→
   116→          // Generic error
   117→          return errorResponse(500, {
   118→            error: error.message || 'Failed to register project',
   119→          });
   120→        }
   121→      },
   122→      {
   123→        body: t.Object({
   124→          path: t.String(),
   125→        }),
   126→      }
   127→    )
