import { test, expect } from '../fixtures/test-base';
import { mkdir } from 'fs/promises';
import { join } from 'path';

/**
 * /api/projects Endpoint Tests
 *
 * Direct HTTP tests for project management API endpoints.
 * Tests make real HTTP requests to running daemon.
 *
 * AC Coverage:
 * - ac-28: GET /api/projects returns list with paths, registration time, watcher status
 * - ac-29: POST /api/projects with {path: string} body manually registers project
 * - ac-30: DELETE /api/projects/:encodedPath unregisters project and stops watcher
 */

test.describe('/api/projects API Endpoints', () => {
  const baseUrl = 'http://localhost:3456';

  // AC: @multi-directory-daemon ac-28
  test('GET /api/projects returns registered projects list', async ({ daemon }) => {
    const response = await fetch(`${baseUrl}/api/projects`);

    expect(response.status).toBe(200);
    expect(response.headers.get('content-type')).toContain('application/json');

    const data = await response.json();

    // AC: @multi-directory-daemon ac-28 - Response structure
    expect(data).toHaveProperty('projects');
    expect(data).toHaveProperty('total');
    expect(Array.isArray(data.projects)).toBe(true);

    // Should have at least the default project (from daemon fixture)
    expect(data.total).toBeGreaterThan(0);
    expect(data.projects.length).toBe(data.total);

    // AC: @multi-directory-daemon ac-28 - Project fields
    const project = data.projects[0];
    expect(project).toHaveProperty('path');
    expect(project).toHaveProperty('registeredAt');
    expect(project).toHaveProperty('watcherStatus');

    // Validate field types
    expect(typeof project.path).toBe('string');
    expect(typeof project.registeredAt).toBe('string'); // ISO timestamp
    expect(['active', 'stopped']).toContain(project.watcherStatus);
  });

  // AC: @multi-directory-daemon ac-29
  test('POST /api/projects manually registers a project', async ({ daemon }) => {
    // Create a valid kspec project in temp directory
    const newProjectPath = join(daemon.tempDir, 'test-project');
    await mkdir(join(newProjectPath, '.kspec'), { recursive: true });

    const response = await fetch(`${baseUrl}/api/projects`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ path: newProjectPath }),
    });

    expect(response.status).toBe(200);

    const data = await response.json();

    // AC: @multi-directory-daemon ac-29 - Response structure
    expect(data).toHaveProperty('success', true);
    expect(data).toHaveProperty('project');

    // Project metadata
    expect(data.project.path).toBe(newProjectPath);
    expect(data.project).toHaveProperty('registeredAt');
    expect(data.project).toHaveProperty('watcherStatus');
    expect(['active', 'stopped']).toContain(data.project.watcherStatus);

    // Verify project is now in the list
    const listResponse = await fetch(`${baseUrl}/api/projects`);
    const listData = await listResponse.json();

    const registered = listData.projects.find((p: any) => p.path === newProjectPath);
    expect(registered).toBeDefined();
  });

  // AC: @multi-directory-daemon ac-29, ac-6
  test('POST /api/projects rejects relative path', async ({ daemon }) => {
    const response = await fetch(`${baseUrl}/api/projects`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ path: './relative/path' }),
    });

    // AC: @multi-directory-daemon ac-6 - Must be absolute
    expect(response.status).toBe(400);

    const data = await response.json();
    expect(data).toHaveProperty('error');
    expect(data.error).toContain('absolute');
  });

  // AC: @multi-directory-daemon ac-29, ac-7
  test('POST /api/projects rejects path with parent traversal', async ({ daemon }) => {
    const response = await fetch(`${baseUrl}/api/projects`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ path: '/tmp/../etc/passwd' }),
    });

    // AC: @multi-directory-daemon ac-7 - Reject ".."
    expect(response.status).toBe(400);

    const data = await response.json();
    expect(data).toHaveProperty('error');
    expect(data.error).toContain('parent traversal');
  });

  // AC: @multi-directory-daemon ac-29, ac-5
  test('POST /api/projects rejects invalid project (no .kspec/)', async ({ daemon }) => {
    const invalidPath = join(daemon.tempDir, 'invalid-project');
    await mkdir(invalidPath, { recursive: true });
    // No .kspec/ directory

    const response = await fetch(`${baseUrl}/api/projects`, {
