const API_BASE = '';

/**
 * Helper to build URL with query params
 * Handles both relative and absolute API_BASE
 */
function buildURL(path: string, params?: Record<string, string | number | boolean | string[] | undefined>): string {
	const base = typeof window !== 'undefined' ? window.location.origin : 'http://localhost:3456';
	const url = new URL(`${API_BASE}${path}`, base);

	if (params) {
