	TaskSummary,
	TaskDetail,
	ItemSummary,
	ItemDetail,
	InboxItem,
	SessionContext,
	Observation,
	PaginatedResponse,
	ErrorResponse,
	SearchResponse
} from '@kynetic-ai/shared';

// Use relative URL to work with Vite proxy during development/testing
// In production (daemon serving static files), this resolves to daemon's API
