/**
 * API Client
 *
 * Helper functions for making requests to the kspec daemon API.
 * All functions use fetch with localhost:3456 as the base URL.
 */

import type {
	TaskSummary,
	TaskDetail,
	ItemSummary,
	ItemDetail,
	InboxItem,
	SessionContext,
	Observation,
	PaginatedResponse,
	ErrorResponse,
	SearchResponse
} from '@kynetic-ai/shared';

// Use relative URL to work with Vite proxy during development/testing
// In production (daemon serving static files), this resolves to daemon's API
const API_BASE = '';

/**
 * Helper to build URL with query params
 * Handles both relative and absolute API_BASE
 */
function buildURL(path: string, params?: Record<string, string | number | boolean | string[] | undefined>): string {
	const base = typeof window !== 'undefined' ? window.location.origin : 'http://localhost:3456';
	const url = new URL(`${API_BASE}${path}`, base);

	if (params) {
		Object.entries(params).forEach(([key, value]) => {
			if (value !== undefined && value !== '') {
				if (Array.isArray(value)) {
					value.forEach((v) => url.searchParams.append(key, String(v)));
				} else {
					url.searchParams.set(key, String(value));
				}
			}
		});
	}

	return url.toString();
}

